};

const maestros = items; 

const botones = maestros.map(maestro => {
  return [{
    text: maestro.json.nombre, 
    callback_data: `lista# ${maestro.json.tutor_id}`
  }];
});

return {
  chat_id: $('recibe el callback_querys').first().json.callback_query.message.chat.id,
  text: "Selecciona un tutor:",
  reply_markup: {
    inline_keyboard: botones
  }
};

// 1. Obtener datos de la hoja
const todosLosDatos = items.map(item => item.json);

const rawValor = $('diferenciar por etiquetas').first().json.valor;
const valorBuscado = String(rawValor).trim();

const datosFiltrados = todosLosDatos.filter(d => {
    const idEnHoja = String(d.tutor_id).trim();
    return idEnHoja === valorBuscado;
});

if (datosFiltrados.length === 0) {
    console.log("DEBUG: Comparando valorBuscado [" + valorBuscado + "] contra los IDs de la hoja.");
    return { 
        json: { text: "No encontré resultados. Busqué el ID: " + valorBuscado } 
    };
}

// 5. Formatear
const nombreProfesor = datosFiltrados[0].nombre;
let mensaje = `📅 *Horarios del maestr@ ${nombreProfesor}:*\n\n`;

datosFiltrados.forEach(row => {
  mensaje += `• *${row.materias}*: ${row.dia} (${row.hora_inicio} - ${row.hora_fin})\n`;
});

return { json: { text: mensaje } };

