const itemJson = items[0].json;
const isCallback = itemJson.callback_query !== undefined;

let tipo = 'menu';
let valor = 'regreso';

let chatId = itemJson.callback_query?.message?.chat?.id || itemJson.message?.chat?.id;
let firstName = itemJson.callback_query?.from?.first_name || itemJson.message?.from?.first_name || "Usuario";

