    tipo = parts[0].trim();
    valor = parts[1].trim(); 
} 
else if (itemJson.message?.text) {
    const textoUsuario = itemJson.message.text.trim().toUpperCase();

    // Verificamos si es formato E000
    if (/^E\d{3}$/.test(textoUsuario)) {
        tipo = 'matricularse';
        valor = textoUsuario; // Asignamos el valor en mayúsculas
    } else {
        // Si no cumple el formato, dejamos tipo 'menu' y valor 'regreso'
        tipo = 'menu';
        valor = 'regreso';
    }
}

return {
  json: {
    tipo: tipo,
    valor: valor,
    chat_id: chatId,
    first_name: firstName 
  }
};

