const webhookInput = $('Webhook').first();
const datosForm = webhookInput ? webhookInput.json.body : null;

if (!datosForm) {
    return [{ json: { status: "error", message: "No se recibieron datos del formulario." } }];
}

const todosLosEstudiantes = (items && items.length > 0 && items[0].json.estudiante_id) ? items : [];

const tipo = datosForm.tipo;

if (tipo === 'registro') {
    const emailExistente = todosLosEstudiantes.find(item => 
        item.json.email && item.json.email.toLowerCase() === datosForm.email.toLowerCase()
    );

    if (emailExistente) {
        return [{ json: { status: "error", message: "Lo siento, ese email ya se encuentra registrado." } }];
    }

    const lastId = todosLosEstudiantes.length > 0 
        ? todosLosEstudiantes[todosLosEstudiantes.length - 1].json.estudiante_id 
        : "E000";

    const number = parseInt(lastId.substring(1)) + 1;
    const newId = "E" + number.toString().padStart(3, '0');

    return [{ json: { ...datosForm, estudiante_id: newId, status: "ok" } }];
}

if (tipo === 'matricula') {
    if (todosLosEstudiantes.length === 0) {
         return [{ json: { status: "error", message: "No hay registros de estudiantes para matricular." } }];
    }

    const estudianteExiste = todosLosEstudiantes.find(item => 
        item.json.estudiante_id === datosForm.estudiante_id
    );

    if (!estudianteExiste) {
        return [{ json: { status: "error", message: "El código de estudiante no existe. Por favor verifica." } }];
    }

    return [{ json: { ...datosForm, status: "ok" } }];
}

return [{ json: { status: "error", message: "Tipo de operación no reconocida." } }];

// 1. Obtenemos el ID de la materia seleccionada (desde el nodo anterior)
const materiaSeleccionada = $('Update row in sheet').first().json.materia_id;

// 2. Filtramos usando la propiedad correcta 'id_materia'
const horarios = items.filter(item => {
    // Usamos 'id_materia' que es el nombre real que aparece en tu columna de entrada
    const idEnFila = String(item.json.id_materia || "").trim();
    return idEnFila.toUpperCase() === String(materiaSeleccionada).toUpperCase();
});

// DEBUG para ver en los logs qué está pasando
console.log("Materia buscada:", materiaSeleccionada);
console.log("Horarios encontrados:", horarios.length);

// 3. Formateamos los botones
const botones = horarios.map(h => [{
    text: `${h.json.dia} - ${h.json.hora_inicio} a ${h.json.hora_fin}`,
    callback_data: `confirmar#${h.json.horario_id}`
}]);

// 4. Retorno
return [{
  json: {
    text: horarios.length > 0 
      ? `Horarios disponibles para *${horarios[0].json.materias}*:` 
      : "No se encontraron horarios para la materia seleccionada (" + materiaSeleccionada + ").",
    reply_markup: {
      inline_keyboard: botones
    }
  }
}];

// Referencia al nodo anterior por su nombre exacto
const filas = $('obtener matricula1').all(); 

if (filas.length > 0) {
    // Tomamos la última fila encontrada
    const ultimaFila = filas[filas.length - 1]; 

    // Obtenemos el número de fila de la propiedad que entrega Google Sheets
    const numeroFila = ultimaFila.json.row_number; 

    return [{
        json: {
            fila: numeroFila,
            // Extraemos el ID del horario del nodo que recibe el webhook
            horario_id: $('recibe el callback_querys').first().json.callback_query.data.split('#')[1]
        }
    }];
}

